#!/bin/bash
# Generates ~/.config/btop/themes/wal.theme from pywal colors
# Run once after setup, then again via wallpaper-picker on each change

source ~/.cache/wal/colors.sh

THEME_DIR="$HOME/.config/btop/themes"
mkdir -p "$THEME_DIR"

cat > "$THEME_DIR/wal.theme" << EOF
# Generated by pywal — do not edit manually
theme[main_bg]="${background}"
theme[main_fg]="${foreground}"
theme[title]="${color3}"
theme[hi_fg]="${color3}"
theme[selected_bg]="${color1}"
theme[selected_fg]="${foreground}"
theme[inactive_fg]="${color8}"
theme[graph_text]="${foreground}"
theme[meter_bg]="${color0}"
theme[proc_misc]="${color4}"
theme[cpu_box]="${color4}"
theme[mem_box]="${color4}"
theme[net_box]="${color4}"
theme[proc_box]="${color4}"
theme[div_line]="${color8}"
theme[temp_start]="${color2}"
theme[temp_mid]="${color3}"
theme[temp_end]="${color1}"
theme[cpu_start]="${color2}"
theme[cpu_mid]="${color3}"
theme[cpu_end]="${color1}"
theme[free_start]="${color4}"
theme[free_mid]="${color8}"
theme[free_end]="${color1}"
theme[cached_start]="${color2}"
theme[cached_mid]="${color3}"
theme[cached_end]="${color1}"
theme[available_start]="${color4}"
theme[available_mid]="${color8}"
theme[available_end]="${color3}"
theme[used_start]="${color2}"
theme[used_mid]="${color3}"
theme[used_end]="${color1}"
theme[download_start]="${color4}"
theme[download_mid]="${color8}"
theme[download_end]="${color3}"
theme[upload_start]="${color2}"
theme[upload_mid]="${color3}"
theme[upload_end]="${color1}"
theme[process_start]="${color2}"
theme[process_mid]="${color3}"
theme[process_end]="${color1}"
EOF

echo "btop theme written to $THEME_DIR/wal.theme"
